   1→import { useEffect, useRef, useState } from "react";
   2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
   3→import { useLoaderData, useFetcher, redirect, useNavigate } from "react-router";
   4→import { useAppBridge } from "@shopify/app-bridge-react";
   5→import { authenticate } from "../shopify.server";
   6→import db from "../db.server";
   7→import {
   8→  Page,
   9→  Layout,
  10→  Card,
  11→  BlockStack,
  12→  InlineStack,
  13→  Text,
  14→  Badge,
  15→  Button,
  16→  ButtonGroup,
  17→  Banner,
  18→  TextField,
  19→  Select,
  20→  Checkbox,
  21→  List,
  22→  Tabs,
  23→  ChoiceList,
  24→  ResourceList,
  25→  ResourceItem,
  26→  EmptyState,
  27→  Tooltip,
  28→  Box,
  29→  Divider,
  30→} from "@shopify/polaris";
  31→
  32→// ---------------------------------------------------------------------------
  33→// Types
  34→// ---------------------------------------------------------------------------
  35→
  36→interface DisplaySettings {
  37→  priority: number;
  38→  countries: "all" | "selected";
  39→  selectedCountries: string;
  40→  buttonPosition: "floating" | "above_desc" | "below_desc";
  41→}
  42→
  43→interface ChartData {
  44→  headers: string[];
  45→  units: { default: string; available: string[] };
  46→  rows: Record<string, string>[];
  47→  displaySettings?: DisplaySettings;
  48→  recommendationEnabled?: boolean;
  49→}
  50→
  51→interface Assignment {
  52→  id: string;
  53→  assignmentType: string;
  54→  assignmentValue: string;
  55→}
  56→
  57→// ---------------------------------------------------------------------------
  58→// Loader
  59→// ---------------------------------------------------------------------------
  60→
  61→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  62→  const { session } = await authenticate.admin(request);
  63→  const shop = session.shop;
  64→  const id = params.id;
  65→
  66→  if (!id) throw new Response("Not found", { status: 404 });
  67→
  68→  if (id === "new") {
  69→    return {
  70→      chart: null as null,
  71→      assignments: [] as Assignment[],
  72→      isNew: true,
  73→    };
  74→  }
  75→
  76→  const chart = await db.sizeChart.findFirst({
  77→    where: { id, shop },
  78→    include: { assignments: true },
  79→  });
  80→
  81→  if (!chart) {
  82→    throw new Response("Not found", { status: 404 });
  83→  }
  84→
  85→  return {
  86→    chart: {
  87→      id: chart.id,
  88→      name: chart.name,
  89→      category: chart.category,
  90→      status: chart.status,
  91→      data: chart.data,
  92→      createdAt: chart.createdAt.toISOString(),
  93→      updatedAt: chart.updatedAt.toISOString(),
  94→    },
  95→    assignments: chart.assignments.map((a) => ({
  96→      id: a.id,
  97→      assignmentType: a.assignmentType,
  98→      assignmentValue: a.assignmentValue,
  99→    })),
 100→    isNew: false,
 101→  };
 102→};
 103→
 104→// ---------------------------------------------------------------------------
 105→// Action
 106→// ---------------------------------------------------------------------------
 107→
 108→export const action = async ({ request, params }: ActionFunctionArgs) => {
 109→  const { session } = await authenticate.admin(request);
 110→  const shop = session.shop;
 111→  const id = params.id;
 112→  if (!id) return { error: "Missing chart ID" };
 113→  const formData = await request.formData();
 114→  const intent = formData.get("intent") as string;
 115→
 116→  try {
 117→    switch (intent) {
 118→      case "save": {
 119→        const name = formData.get("name") as string;
 120→        const category = formData.get("category") as string;
 121→        const status = formData.get("status") as string;
 122→        const dataRaw = formData.get("data") as string;
 123→
 124→        if (!name?.trim()) return { error: "Chart name is required" };
 125→
 126→        let parsedData: ChartData;
 127→        try {
 128→          parsedData = JSON.parse(dataRaw) as ChartData;
 129→        } catch {
 130→          return { error: "Invalid chart data. Please try again." };
 131→        }
 132→
 133→        if (id === "new") {
 134→          const chart = await db.sizeChart.create({
 135→            data: {
 136→              shop,
 137→              name: name.trim(),
 138→              category,
 139→              status,
 140→              data: JSON.stringify(parsedData),
 141→            },
 142→          });
 143→          return redirect(`/app/size-charts/${chart.id}?saved=1`);
 144→        }
 145→
 146→        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
 147→        if (!existing) return { error: "Chart not found" };
 148→
 149→        await db.sizeChart.updateMany({
 150→          where: { id, shop },
 151→          data: {
 152→            name: name.trim(),
 153→            category,
 154→            status,
 155→            data: JSON.stringify(parsedData),
 156→          },
 157→        });
 158→        return { ok: true, message: "Chart saved successfully" };
 159→      }
 160→
 161→      case "toggle-status": {
 162→        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
 163→        if (!chart) return { error: "Chart not found" };
 164→        const newStatus = chart.status === "active" ? "draft" : "active";
 165→        await db.sizeChart.updateMany({ where: { id, shop }, data: { status: newStatus } });
 166→        return {
 167→          ok: true,
 168→          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
 169→          newStatus,
 170→        };
 171→      }
 172→
 173→      case "add-assignment": {
 174→        const assignmentType = formData.get("assignmentType") as string;
 175→        const assignmentValue = formData.get("assignmentValue") as string;
 176→
 177→        if (!assignmentValue?.trim()) {
 178→          return { error: "Assignment value is required" };
 179→        }
 180→
 181→        await db.chartAssignment.upsert({
 182→          where: {
 183→            shop_sizeChartId_assignmentType_assignmentValue: {
 184→              shop,
 185→              sizeChartId: id,
 186→              assignmentType,
 187→              assignmentValue: assignmentValue.trim(),
 188→            },
 189→          },
 190→          create: {
 191→            shop,
 192→            sizeChartId: id,
 193→            assignmentType,
 194→            assignmentValue: assignmentValue.trim(),
 195→          },
 196→          update: {},
 197→        });
 198→        return { ok: true, message: "Assignment added" };
 199→      }
 200→
 201→      case "remove-assignment": {
 202→        const assignmentId = formData.get("assignmentId") as string;
 203→        await db.chartAssignment.deleteMany({
 204→          where: { id: assignmentId, shop },
 205→        });
 206→        return { ok: true, message: "Assignment removed" };
 207→      }
 208→
 209→      case "delete": {
 210→        await db.sizeChart.deleteMany({ where: { id, shop } });
 211→        return redirect("/app/size-charts");
 212→      }
 213→
 214→      default:
 215→        return { error: "Unknown action" };
 216→    }
 217→  } catch (error) {
 218→    const message =
 219→      error instanceof Error ? error.message : "An unexpected error occurred";
 220→    if (message.includes("Unique constraint")) {
 221→      return { error: "A chart with this name already exists." };
 222→    }
 223→    return { error: message };
 224→  }
 225→};
