 250→function formatDate(iso: string): string {
 251→  return new Date(iso).toLocaleDateString("en-US", {
 252→    month: "short",
 253→    day: "numeric",
 254→    year: "numeric",
 255→    hour: "2-digit",
 256→    minute: "2-digit",
 257→  });
 258→}
 259→
 260→function makeDefaultData(): ChartData {
 261→  return {
 262→    headers: ["Size", "Chest", "Waist", "Hips"],
 263→    units: { default: "in", available: ["in", "cm"] },
 264→    rows: [
 265→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 266→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 267→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 268→    ],
 269→  };
 270→}
 271→
 272→function parseChartData(raw: string): ChartData {
 273→  try {
 274→    const parsed = JSON.parse(raw) as ChartData;
 275→    if (
 276→      Array.isArray(parsed.headers) &&
 277→      parsed.units &&
 278→      Array.isArray(parsed.rows)
 279→    ) {
 280→      return parsed;
 281→    }
 282→  } catch {
 283→    // fall through
 284→  }
 285→  return makeDefaultData();
 286→}
