 288→// ---------------------------------------------------------------------------
 289→// Table Editor Component
 290→// ---------------------------------------------------------------------------
 291→
 292→interface TableEditorProps {
 293→  data: ChartData;
 294→  onChange: (data: ChartData) => void;
 295→}
 296→
 297→function TableEditor({ data, onChange }: TableEditorProps) {
 298→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 299→
 300→  const updateCell = (rowIndex: number, header: string, value: string) => {
 301→    const newRows = data.rows.map((row, i) => {
 302→      if (i !== rowIndex) return row;
 303→      return { ...row, [header]: value };
 304→    });
 305→    onChange({ ...data, rows: newRows });
 306→  };
 307→
 308→  const updateHeader = (headerIndex: number, value: string) => {
 309→    const oldHeader = data.headers[headerIndex];
 310→    const newHeaders = data.headers.map((h, i) =>
 311→      i === headerIndex ? value : h,
 312→    );
 313→    const newRows = data.rows.map((row) => {
 314→      const newRow: Record<string, string> = {};
 315→      data.headers.forEach((h, i) => {
 316→        const key = i === headerIndex ? value : h;
 317→        newRow[key] = row[h] ?? "";
 318→      });
 319→      return newRow;
 320→    });
 321→    onChange({ ...data, headers: newHeaders, rows: newRows });
 322→    void oldHeader;
 323→  };
 324→
 325→  const addRow = () => {
 326→    const emptyRow: Record<string, string> = {};
 327→    data.headers.forEach((h) => {
 328→      emptyRow[h] = "";
 329→    });
 330→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 331→  };
 332→
 333→  const removeRow = (rowIndex: number) => {
 334→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 335→  };
 336→
 337→  const addColumn = () => {
 338→    const newHeader = `Column ${data.headers.length + 1}`;
 339→    const newHeaders = [...data.headers, newHeader];
 340→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 341→    onChange({ ...data, headers: newHeaders, rows: newRows });
 342→  };
 343→
 344→  const removeColumn = (headerIndex: number) => {
 345→    if (data.headers.length <= 1) return;
 346→    const removedHeader = data.headers[headerIndex];
 347→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 348→    const newRows = data.rows.map((row) => {
 349→      const newRow: Record<string, string> = {};
 350→      newHeaders.forEach((h) => {
 351→        newRow[h] = row[h] ?? "";
 352→      });
 353→      return newRow;
 354→    });
 355→    onChange({ ...data, headers: newHeaders, rows: newRows });
 356→    void removedHeader;
 357→  };
 358→
 359→  const toggleUnit = (unit: string) => {
 360→    onChange({ ...data, units: { ...data.units, default: unit } });
 361→  };
 362→
 363→  return (
 364→    <BlockStack gap="300">
 365→      {/* Toolbar -- unit toggle + row/col count */}
 366→      <InlineStack gap="300" align="start" blockAlign="center">
 367→        <Text as="span" variant="bodySm" tone="subdued" fontWeight="semibold">
 368→          Units
 369→        </Text>
 370→        <ButtonGroup variant="segmented">
 371→          {data.units.available.map((unit) => (
 372→            <Button
 373→              key={unit}
 374→              pressed={data.units.default === unit}
 375→              onClick={() => toggleUnit(unit)}
 376→              size="slim"
 377→            >
 378→              {unit}
 379→            </Button>
 380→          ))}
 381→        </ButtonGroup>
 382→        <div style={{ marginLeft: "auto" }}>
 383→          <Badge>
 384→            {`${data.rows.length} rows \u00b7 ${data.headers.length} cols`}
 385→          </Badge>
 386→        </div>
 387→      </InlineStack>
 388→
 389→      {/* Table */}
 390→      <div
 391→        style={{
 392→          border: "1px solid #e1e3e5",
 393→          borderRadius: "8px",
 394→          overflow: "hidden",
 395→          overflowX: "auto",
 396→        }}
 397→      >
 398→        <table
 399→          style={{
 400→            width: "100%",
 401→            borderCollapse: "collapse",
 402→            fontSize: "13px",
 403→            tableLayout: "auto",
 404→          }}
 405→        >
 406→          <thead>
 407→            <tr>
 408→              {data.headers.map((header, hi) => (
 409→                <th
 410→                  key={hi}
 411→                  style={{
 412→                    background: "#f6f6f7",
 413→                    borderBottom: "2px solid #e1e3e5",
 414→                    borderRight:
 415→                      hi < data.headers.length - 1
 416→                        ? "1px solid #e1e3e5"
 417→                        : "none",
 418→                    padding: "0",
 419→                    position: "relative",
 420→                    minWidth: "110px",
 421→                  }}
 422→                >
 423→                  <div
 424→                    style={{
 425→                      display: "flex",
 426→                      alignItems: "center",
 427→                      padding: "2px 6px 2px 10px",
 428→                    }}
 429→                  >
 430→                    <input
 431→                      ref={(el) => {
 432→                        headerInputRefs.current[hi] = el;
 433→                      }}
 434→                      value={header}
 435→                      onChange={(e) =>
 436→                        updateHeader(hi, (e.target as HTMLInputElement).value)
 437→                      }
 438→                      style={{
 439→                        flex: 1,
 440→                        border: "none",
 441→                        background: "transparent",
 442→                        fontWeight: 700,
 443→                        fontSize: "12px",
 444→                        color: "#202223",
 445→                        padding: "8px 4px",
 446→                        outline: "none",
 447→                        minWidth: "60px",
 448→                        textTransform: "uppercase",
 449→                        letterSpacing: "0.04em",
 450→                        fontFamily: "inherit",
 451→                      }}
 452→                      placeholder={`Col ${hi + 1}`}
 453→                    />
 454→                    {data.headers.length > 1 && (
 455→                      <Tooltip content="Remove column" dismissOnMouseOut>
 456→                        <Button
 457→                          variant="plain"
 458→                          tone="critical"
 459→                          onClick={() => removeColumn(hi)}
 460→                          accessibilityLabel={`Remove column ${header}`}
 461→                          size="slim"
 462→                        >
 463→                          &times;
 464→                        </Button>
 465→                      </Tooltip>
 466→                    )}
 467→                  </div>
 468→                </th>
 469→              ))}
 470→
 471→              {/* Add column header cell */}
 472→              <th
 473→                style={{
 474→                  background: "#f6f6f7",
 475→                  borderBottom: "2px solid #e1e3e5",
 476→                  padding: "4px",
 477→                  width: "48px",
 478→                  minWidth: "48px",
 479→                  textAlign: "center",
 480→                }}
 481→              >
 482→                <Tooltip content="Add column" dismissOnMouseOut>
 483→                  <Button
 484→                    variant="plain"
 485→                    onClick={addColumn}
 486→                    accessibilityLabel="Add column"
 487→                    size="slim"
 488→                  >
 489→                    +
 490→                  </Button>
 491→                </Tooltip>
 492→              </th>
 493→
 494→              {/* Row actions header spacer */}
 495→              <th
 496→                style={{
 497→                  background: "#f6f6f7",
 498→                  borderBottom: "2px solid #e1e3e5",
 499→                  width: "36px",
 500→                  minWidth: "36px",
 501→                }}
 502→              />
 503→            </tr>
 504→          </thead>
 505→          <tbody>
 506→            {data.rows.map((row, ri) => (
 507→              <tr
 508→                key={ri}
 509→                style={{
 510→                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
 511→                  transition: "background 0.1s",
 512→                }}
 513→                onMouseEnter={(e) => {
 514→                  (e.currentTarget as HTMLTableRowElement).style.background =
 515→                    "#f0f5ff";
 516→                }}
 517→                onMouseLeave={(e) => {
 518→                  (e.currentTarget as HTMLTableRowElement).style.background =
 519→                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
 520→                }}
 521→              >
 522→                {data.headers.map((header, hi) => (
 523→                  <td
 524→                    key={hi}
 525→                    style={{
 526→                      borderBottom:
 527→                        ri < data.rows.length - 1
 528→                          ? "1px solid #e1e3e5"
 529→                          : "none",
 530→                      borderRight:
 531→                        hi < data.headers.length - 1
 532→                          ? "1px solid #e1e3e5"
 533→                          : "none",
 534→                      padding: "0",
 535→                    }}
 536→                  >
 537→                    <input
 538→                      value={row[header] ?? ""}
 539→                      onChange={(e) =>
 540→                        updateCell(
 541→                          ri,
 542→                          header,
 543→                          (e.target as HTMLInputElement).value,
 544→                        )
 545→                      }
 546→                      style={{
 547→                        width: "100%",
 548→                        border: "none",
 549→                        background: "transparent",
 550→                        padding: "9px 10px",
 551→                        fontSize: "13px",
 552→                        color: "#202223",
 553→                        outline: "none",
 554→                        boxSizing: "border-box",
 555→                        fontFamily: "inherit",
 556→                      }}
 557→                      onFocus={(e) => {
 558→                        (
 559→                          e.target as HTMLInputElement
 560→                        ).parentElement!.style.boxShadow =
 561→                          "inset 0 0 0 2px #2c6ecb";
 562→                        (
 563→                          e.target as HTMLInputElement
 564→                        ).parentElement!.style.background = "#f0f5ff";
 565→                      }}
 566→                      onBlur={(e) => {
 567→                        (
 568→                          e.target as HTMLInputElement
 569→                        ).parentElement!.style.boxShadow = "none";
 570→                        (
 571→                          e.target as HTMLInputElement
 572→                        ).parentElement!.style.background = "transparent";
 573→                      }}
 574→                      placeholder="—"
 575→                    />
 576→                  </td>
 577→                ))}
 578→
 579→                {/* Column spacer — aligns under add column button */}
 580→                <td
 581→                  style={{
 582→                    borderBottom:
 583→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 584→                    borderRight: "1px solid #e1e3e5",
 585→                    width: "40px",
 586→                    background: "transparent",
 587→                  }}
 588→                />
 589→
 590→                {/* Remove row button */}
 591→                <td
 592→                  style={{
 593→                    borderBottom:
 594→                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
 595→                    padding: "4px",
 596→                    textAlign: "center",
 597→                    width: "48px",
 598→                    background: "transparent",
 599→                  }}
 600→                >
 601→                  <Tooltip content="Remove row" dismissOnMouseOut>
 602→                    <Button
 603→                      variant="plain"
 604→                      tone="critical"
 605→                      onClick={() => removeRow(ri)}
 606→                      accessibilityLabel={`Remove row ${ri + 1}`}
 607→                      size="slim"
 608→                    >
 609→                      &times;
 610→                    </Button>
 611→                  </Tooltip>
 612→                </td>
 613→              </tr>
 614→            ))}
 615→
 616→            {/* Add row footer */}
 617→            <tr>
 618→              <td
 619→                colSpan={data.headers.length + 2}
 620→                style={{
 621→                  padding: "8px 12px",
 622→                  background: "#f6f6f7",
 623→                  borderTop: "1px solid #e1e3e5",
 624→                }}
 625→              >
 626→                <Button variant="plain" onClick={addRow}>
 627→                  + Add row
 628→                </Button>
 629→              </td>
 630→            </tr>
 631→          </tbody>
 632→        </table>
 633→      </div>
 634→    </BlockStack>
 635→  );
 636→}
