 638→// ---------------------------------------------------------------------------
 639→// Chart Preview Component — Realistic storefront widget mockup
 640→// ---------------------------------------------------------------------------
 641→
 642→// ---------------------------------------------------------------------------
 643→// Main Component
 644→// ---------------------------------------------------------------------------
 645→
 646→type LoaderData = Awaited<ReturnType<typeof loader>>;
 647→type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";
 648→
 649→export default function SizeChartEditor() {
 650→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 651→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 652→  const navigate = useNavigate();
 653→
 654→  const saveFetcher = useFetcher<typeof action>();
 655→  const statusFetcher = useFetcher<typeof action>();
 656→  const assignmentFetcher = useFetcher<typeof action>();
 657→  const shopify = useAppBridge();
 658→
 659→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
 660→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
 661→  const [category, setCategory] = useState(chart?.category ?? "general");
 662→  const [status, setStatus] = useState(chart?.status ?? "draft");
 663→  const [chartData, setChartData] = useState<ChartData>(
 664→    chart ? parseChartData(chart.data) : makeDefaultData(),
 665→  );
 666→  const [assignments, setAssignments] =
 667→    useState<Assignment[]>(initialAssignments);
 668→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 669→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 670→
 671→  // Position settings (stored in chartData.displaySettings)
 672→  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
 673→  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
 674→  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
 675→  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
 676→  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
 677→  const [recommendationEnabled, setRecommendationEnabled] = useState(
 678→    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 679→  );
 680→
 681→  const isSaving = saveFetcher.state !== "idle";
 682→  const isTogglingStatus = statusFetcher.state !== "idle";
 683→
 684→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 685→  useEffect(() => {
 686→    if (typeof window !== "undefined") {
 687→      const url = new URL(window.location.href);
 688→      if (url.searchParams.get("saved") === "1") {
 689→        shopify.toast.show("Chart created successfully");
 690→        url.searchParams.delete("saved");
 691→        window.history.replaceState({}, "", url.toString());
 692→      }
 693→    }
 694→  }, [shopify]);
 695→
 696→  // Save feedback
 697→  useEffect(() => {
