import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, redirect, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Banner,
  TextField,
  Select,
  Checkbox,
  List,
  Tabs,
  ChoiceList,
  ResourceList,
  ResourceItem,
  EmptyState,
  Tooltip,
  Box,
  Divider,
  InlineGrid,
} from "@shopify/polaris";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface DisplaySettings {
  priority: number;
  countries: "all" | "selected";
  selectedCountries: string;
  buttonPosition: "floating" | "above_desc" | "below_desc";
}

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
  displaySettings?: DisplaySettings;
  recommendationEnabled?: boolean;
}

interface Assignment {
  id: string;
  assignmentType: string;
  assignmentValue: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;

  if (!id) throw new Response("Not found", { status: 404 });

  if (id === "new") {
    return {
      chart: null as null,
      assignments: [] as Assignment[],
      isNew: true,
    };
  }

  const chart = await db.sizeChart.findFirst({
    where: { id, shop },
    include: { assignments: true },
  });

  if (!chart) {
    throw new Response("Not found", { status: 404 });
  }

  return {
    chart: {
      id: chart.id,
      name: chart.name,
      category: chart.category,
      status: chart.status,
      data: chart.data,
      createdAt: chart.createdAt.toISOString(),
      updatedAt: chart.updatedAt.toISOString(),
    },
    assignments: chart.assignments.map((a) => ({
      id: a.id,
      assignmentType: a.assignmentType,
      assignmentValue: a.assignmentValue,
    })),
    isNew: false,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;
  if (!id) return { error: "Missing chart ID" };
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "save": {
        const name = formData.get("name") as string;
        const category = formData.get("category") as string;
        const status = formData.get("status") as string;
        const dataRaw = formData.get("data") as string;

        if (!name?.trim()) return { error: "Chart name is required" };

        let parsedData: ChartData;
        try {
          parsedData = JSON.parse(dataRaw) as ChartData;
        } catch {
          return { error: "Invalid chart data. Please try again." };
        }

        if (id === "new") {
          const chart = await db.sizeChart.create({
            data: {
              shop,
              name: name.trim(),
              category,
              status,
              data: JSON.stringify(parsedData),
            },
          });
          return redirect(`/app/size-charts/${chart.id}?saved=1`);
        }

        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!existing) return { error: "Chart not found" };

        await db.sizeChart.updateMany({
          where: { id, shop },
          data: {
            name: name.trim(),
            category,
            status,
            data: JSON.stringify(parsedData),
          },
        });
        return { ok: true, message: "Chart saved successfully" };
      }

      case "toggle-status": {
        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!chart) return { error: "Chart not found" };
        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.updateMany({ where: { id, shop }, data: { status: newStatus } });
        return {
          ok: true,
          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
          newStatus,
        };
      }

      case "duplicate": {
        const source = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!source) return { error: "Chart not found" };

        const copy = await db.sizeChart.create({
          data: {
            shop,
            name: `${source.name} (Copy)`,
            type: source.type,
            category: source.category,
            status: "draft",
            data: source.data,
          },
        });
        return redirect(`/app/size-charts/${copy.id}?saved=1`);
      }

      case "add-assignment": {
        const assignmentType = formData.get("assignmentType") as string;
        const assignmentValue = formData.get("assignmentValue") as string;

        if (!assignmentValue?.trim()) {
          return { error: "Assignment value is required" };
        }

        await db.chartAssignment.upsert({
          where: {
            shop_sizeChartId_assignmentType_assignmentValue: {
              shop,
              sizeChartId: id,
              assignmentType,
              assignmentValue: assignmentValue.trim(),
            },
          },
          create: {
            shop,
            sizeChartId: id,
            assignmentType,
            assignmentValue: assignmentValue.trim(),
          },
          update: {},
        });
        return { ok: true, message: "Assignment added" };
      }

      case "remove-assignment": {
        const assignmentId = formData.get("assignmentId") as string;
        await db.chartAssignment.deleteMany({
          where: { id: assignmentId, shop },
        });
        return { ok: true, message: "Assignment removed" };
      }

      case "delete": {
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return redirect("/app/size-charts");
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const CATEGORIES = [
  { value: "general", label: "General" },
  { value: "tops", label: "Tops" },
  { value: "bottoms", label: "Bottoms" },
  { value: "dresses", label: "Dresses" },
  { value: "shoes", label: "Shoes" },
  { value: "kids", label: "Kids" },
  { value: "rings", label: "Rings" },
  { value: "sportswear", label: "Sportswear" },
];

const ASSIGNMENT_TYPES = [
  { value: "product", label: "Product ID" },
  { value: "collection", label: "Collection ID" },
  { value: "tag", label: "Product Tag" },
  { value: "product_type", label: "Product Type" },
  { value: "all", label: "All Products" },
];

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function makeDefaultData(): ChartData {
  return {
    headers: ["Size", "Chest", "Waist", "Hips"],
    units: { default: "in", available: ["in", "cm"] },
    rows: [
      { Size: "S", Chest: "", Waist: "", Hips: "" },
      { Size: "M", Chest: "", Waist: "", Hips: "" },
      { Size: "L", Chest: "", Waist: "", Hips: "" },
    ],
  };
}

function parseChartData(raw: string): ChartData {
  try {
    const parsed = JSON.parse(raw) as ChartData;
    if (
      Array.isArray(parsed.headers) &&
      parsed.units &&
      Array.isArray(parsed.rows)
    ) {
      return parsed;
    }
  } catch {
    // fall through
  }
  return makeDefaultData();
}

// ---------------------------------------------------------------------------
// Table Editor Component
// ---------------------------------------------------------------------------

interface TableEditorProps {
  data: ChartData;
  onChange: (data: ChartData) => void;
}

function TableEditor({ data, onChange }: TableEditorProps) {
  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const updateCell = (rowIndex: number, header: string, value: string) => {
    const newRows = data.rows.map((row, i) => {
      if (i !== rowIndex) return row;
      return { ...row, [header]: value };
    });
    onChange({ ...data, rows: newRows });
  };

  const updateHeader = (headerIndex: number, value: string) => {
    const oldHeader = data.headers[headerIndex];
    const newHeaders = data.headers.map((h, i) =>
      i === headerIndex ? value : h,
    );
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      data.headers.forEach((h, i) => {
        const key = i === headerIndex ? value : h;
        newRow[key] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void oldHeader;
  };

  const addRow = () => {
    const emptyRow: Record<string, string> = {};
    data.headers.forEach((h) => {
      emptyRow[h] = "";
    });
    onChange({ ...data, rows: [...data.rows, emptyRow] });
  };

  const removeRow = (rowIndex: number) => {
    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
  };

  const addColumn = () => {
    const newHeader = `Column ${data.headers.length + 1}`;
    const newHeaders = [...data.headers, newHeader];
    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
    onChange({ ...data, headers: newHeaders, rows: newRows });
  };

  const removeColumn = (headerIndex: number) => {
    if (data.headers.length <= 1) return;
    const removedHeader = data.headers[headerIndex];
    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      newHeaders.forEach((h) => {
        newRow[h] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void removedHeader;
  };

  const toggleUnit = (unit: string) => {
    onChange({ ...data, units: { ...data.units, default: unit } });
  };

  return (
    <BlockStack gap="300">
      {/* CSS for focus/hover — replaces inline DOM manipulation */}
      <style>{`
        .chart-row:hover { background: #f0f5ff !important; }
        .chart-cell:focus-within {
          box-shadow: inset 0 0 0 2px var(--p-color-border-focus);
          background: #f0f5ff;
        }
        .chart-cell-input {
          width: 100%;
          border: none;
          background: transparent;
          padding: 9px 10px;
          font-size: 13px;
          color: #202223;
          outline: none;
          box-sizing: border-box;
          font-family: inherit;
        }
        .chart-header-input {
          flex: 1;
          border: none;
          background: transparent;
          font-weight: 700;
          font-size: 12px;
          color: #202223;
          padding: 8px 4px;
          outline: none;
          min-width: 60px;
          text-transform: uppercase;
          letter-spacing: 0.04em;
          font-family: inherit;
        }
      `}</style>

      {/* Toolbar -- unit toggle + row/col count */}
      <InlineStack gap="300" align="start" blockAlign="center">
        <Text as="span" variant="bodySm" tone="subdued" fontWeight="semibold">
          Units
        </Text>
        <ButtonGroup variant="segmented">
          {data.units.available.map((unit) => (
            <Button
              key={unit}
              pressed={data.units.default === unit}
              onClick={() => toggleUnit(unit)}
              size="slim"
            >
              {unit}
            </Button>
          ))}
        </ButtonGroup>
        <div style={{ marginLeft: "auto" }}>
          <Badge>
            {`${data.rows.length} rows \u00b7 ${data.headers.length} cols`}
          </Badge>
        </div>
      </InlineStack>

      {/* Table */}
      <div
        style={{
          border: "1px solid #e1e3e5",
          borderRadius: "8px",
          overflow: "hidden",
          overflowX: "auto",
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
            tableLayout: "auto",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    borderBottom: "2px solid #e1e3e5",
                    borderRight:
                      hi < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    padding: "0",
                    position: "relative",
                    minWidth: "110px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "2px 6px 2px 10px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      className="chart-header-input"
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <Tooltip content="Remove column" dismissOnMouseOut>
                        <Button
                          variant="plain"
                          tone="critical"
                          onClick={() => removeColumn(hi)}
                          accessibilityLabel={`Remove column ${header}`}
                          size="slim"
                        >
                          &times;
                        </Button>
                      </Tooltip>
                    )}
                  </div>
                </th>
              ))}

              {/* Add column header cell */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  padding: "4px",
                  width: "48px",
                  minWidth: "48px",
                  textAlign: "center",
                }}
              >
                <Tooltip content="Add column" dismissOnMouseOut>
                  <Button
                    variant="plain"
                    onClick={addColumn}
                    accessibilityLabel="Add column"
                    size="slim"
                  >
                    +
                  </Button>
                </Tooltip>
              </th>

              {/* Row actions header spacer */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  width: "36px",
                  minWidth: "36px",
                }}
              />
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                className="chart-row"
                style={{
                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
                }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    className="chart-cell"
                    style={{
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(
                          ri,
                          header,
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      className="chart-cell-input"
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column spacer — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "4px",
                    textAlign: "center",
                    width: "48px",
                    background: "transparent",
                  }}
                >
                  <Tooltip content="Remove row" dismissOnMouseOut>
                    <Button
                      variant="plain"
                      tone="critical"
                      onClick={() => removeRow(ri)}
                      accessibilityLabel={`Remove row ${ri + 1}`}
                      size="slim"
                    >
                      &times;
                    </Button>
                  </Tooltip>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "8px 12px",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <Button variant="plain" onClick={addRow}>
                  + Add row
                </Button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// Chart Preview Component — mini table for sidebar
// ---------------------------------------------------------------------------

interface ChartPreviewProps {
  data: ChartData;
  status: string;
  category: string;
  assignmentCount: number;
}

function ChartPreview({ data, status, category, assignmentCount }: ChartPreviewProps) {
  const maxPreviewRows = 4;
  const visibleRows = data.rows.slice(0, maxPreviewRows);
  const remainingRows = data.rows.length - maxPreviewRows;

  return (
    <Card>
      <BlockStack gap="400">
        <Text as="h2" variant="headingMd" fontWeight="bold">
          Preview
        </Text>

        {/* Status + Category badges */}
        <InlineStack gap="200">
          <Badge tone={status === "active" ? "success" : undefined}>
            {status === "active" ? "Published" : "Draft"}
          </Badge>
          <Badge tone="info">{category}</Badge>
          <Badge>{data.units.default}</Badge>
        </InlineStack>

        {/* Mini table preview */}
        <Box borderWidth="025" borderColor="border" borderRadius="200" overflow="hidden">
          <BlockStack>
            {/* Header row */}
            <Box background="bg-surface-secondary" padding="200" paddingInlineStart="300" paddingInlineEnd="300">
              <InlineGrid columns={data.headers.length}>
                {data.headers.map((header) => (
                  <Text key={header} as="span" variant="bodySm" fontWeight="bold" tone="subdued">
                    {header}
                  </Text>
                ))}
              </InlineGrid>
            </Box>

            {/* Data rows */}
            {visibleRows.map((row, ri) => (
              <Box
                key={ri}
                padding="200"
                paddingInlineStart="300"
                paddingInlineEnd="300"
                background={ri % 2 === 0 ? "bg-surface" : "bg-surface-secondary"}
              >
                <InlineGrid columns={data.headers.length}>
                  {data.headers.map((header) => (
                    <Text
                      key={header}
                      as="span"
                      variant="bodySm"
                      fontWeight={header === data.headers[0] ? "semibold" : "regular"}
                    >
                      {row[header] || "\u2014"}
                    </Text>
                  ))}
                </InlineGrid>
              </Box>
            ))}

            {/* More rows indicator */}
            {remainingRows > 0 && (
              <Box padding="200" paddingInlineStart="300">
                <Text as="span" variant="bodySm" tone="subdued">
                  ... and {remainingRows} more row{remainingRows > 1 ? "s" : ""}
                </Text>
              </Box>
            )}
          </BlockStack>
        </Box>

        {/* Quick stats */}
        <Divider />
        <BlockStack gap="200">
          <InlineStack align="space-between">
            <Text as="span" variant="bodySm" tone="subdued">Rows</Text>
            <Text as="span" variant="bodySm">{data.rows.length}</Text>
          </InlineStack>
          <InlineStack align="space-between">
            <Text as="span" variant="bodySm" tone="subdued">Columns</Text>
            <Text as="span" variant="bodySm">{data.headers.length}</Text>
          </InlineStack>
          <InlineStack align="space-between">
            <Text as="span" variant="bodySm" tone="subdued">Assignments</Text>
            <Text as="span" variant="bodySm">{assignmentCount}</Text>
          </InlineStack>
        </BlockStack>

        {/* Hint */}
        <Box
          padding="300"
          background="bg-surface-secondary"
          borderRadius="200"
        >
          <Text as="p" variant="bodySm" tone="subdued">
            Add the Size Chart widget block in your theme editor to display charts on product pages.
          </Text>
        </Box>
      </BlockStack>
    </Card>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

type LoaderData = Awaited<ReturnType<typeof loader>>;
type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";

export default function SizeChartEditor() {
  const loaderData = useLoaderData<typeof loader>() as LoaderData;
  const { chart, assignments: initialAssignments, isNew } = loaderData;
  const navigate = useNavigate();

  const saveFetcher = useFetcher<typeof action>();
  const statusFetcher = useFetcher<typeof action>();
  const assignmentFetcher = useFetcher<typeof action>();
  const duplicateFetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
  const [category, setCategory] = useState(chart?.category ?? "general");
  const [status, setStatus] = useState(chart?.status ?? "draft");
  const [chartData, setChartData] = useState<ChartData>(
    chart ? parseChartData(chart.data) : makeDefaultData(),
  );
  const [assignments, setAssignments] =
    useState<Assignment[]>(initialAssignments);
  const [newAssignmentType, setNewAssignmentType] = useState("product");
  const [newAssignmentValue, setNewAssignmentValue] = useState("");

  // Position settings (stored in chartData.displaySettings)
  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
  const [recommendationEnabled, setRecommendationEnabled] = useState(
    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
  );

  // Track initial values for unsaved changes detection
  const initialValues = useRef({
    name: chart?.name ?? "Untitled Size Chart",
    category: chart?.category ?? "general",
    status: chart?.status ?? "draft",
    chartData: chart ? parseChartData(chart.data) : makeDefaultData(),
    priority: _parsedSettings?.priority ?? 1,
    countries: _parsedSettings?.countries ?? "all",
    selectedCountries: _parsedSettings?.selectedCountries ?? "",
    buttonPosition: _parsedSettings?.buttonPosition ?? "floating",
    recommendationEnabled: chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
  });

  const hasUnsavedChanges = useMemo(() => {
    const init = initialValues.current;
    if (name !== init.name) return true;
    if (category !== init.category) return true;
    if (status !== init.status) return true;
    if (priority !== init.priority) return true;
    if (countries !== init.countries) return true;
    if (selectedCountries !== init.selectedCountries) return true;
    if (buttonPosition !== init.buttonPosition) return true;
    if (recommendationEnabled !== init.recommendationEnabled) return true;
    if (JSON.stringify(chartData) !== JSON.stringify(init.chartData)) return true;
    return false;
  }, [name, category, status, chartData, priority, countries, selectedCountries, buttonPosition, recommendationEnabled]);

  const isSaving = saveFetcher.state !== "idle";
  const isTogglingStatus = statusFetcher.state !== "idle";
  const isDuplicating = duplicateFetcher.state !== "idle";

  // Check for ?saved=1 on mount (after redirect from new chart creation)
  useEffect(() => {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      if (url.searchParams.get("saved") === "1") {
        shopify.toast.show("Chart created successfully");
        url.searchParams.delete("saved");
        window.history.replaceState({}, "", url.toString());
      }
    }
  }, [shopify]);

  // Save feedback — also reset initial values on success
  useEffect(() => {
    if (!saveFetcher.data) return;
    const data = saveFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Saved");
      initialValues.current = {
        name,
        category,
        status,
        chartData,
        priority,
        countries,
        selectedCountries,
        buttonPosition,
        recommendationEnabled,
      };
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [saveFetcher.data, shopify, name, category, status, chartData, priority, countries, selectedCountries, buttonPosition, recommendationEnabled]);

  // Status toggle feedback
  useEffect(() => {
    if (!statusFetcher.data) return;
    const data = statusFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Status updated");
      if ("newStatus" in data && typeof data.newStatus === "string") {
        setStatus(data.newStatus);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [statusFetcher.data, shopify]);

  // Assignment feedback
  useEffect(() => {
    if (!assignmentFetcher.data) return;
    const data = assignmentFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Done");
      setNewAssignmentValue("");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [assignmentFetcher.data, shopify]);

  // Duplicate feedback
  useEffect(() => {
    if (!duplicateFetcher.data) return;
    const data = duplicateFetcher.data;
    if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [duplicateFetcher.data, shopify]);

  const handleSave = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "save");
    formData.set("name", name);
    formData.set("category", category);
    formData.set("status", status);
    const fullData: ChartData = {
      ...chartData,
      displaySettings: { priority, countries, selectedCountries, buttonPosition },
      recommendationEnabled,
    };
    formData.set("data", JSON.stringify(fullData));
    saveFetcher.submit(formData, { method: "post" });
  }, [name, category, status, chartData, priority, countries, selectedCountries, buttonPosition, recommendationEnabled, saveFetcher]);

  const handleToggleStatus = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "toggle-status");
    statusFetcher.submit(formData, { method: "post" });
  }, [statusFetcher]);

  const handleDuplicate = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "duplicate");
    duplicateFetcher.submit(formData, { method: "post" });
  }, [duplicateFetcher]);

  const handleAddAssignment = useCallback(() => {
    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
    const formData = new FormData();
    formData.set("intent", "add-assignment");
    formData.set("assignmentType", newAssignmentType);
    formData.set(
      "assignmentValue",
      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
    );
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        assignmentType: newAssignmentType,
        assignmentValue:
          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
      },
    ]);
  }, [newAssignmentType, newAssignmentValue, assignmentFetcher]);

  const handleRemoveAssignment = useCallback((assignmentId: string) => {
    const formData = new FormData();
    formData.set("intent", "remove-assignment");
    formData.set("assignmentId", assignmentId);
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  }, [assignmentFetcher]);

  const assignmentTypeLabel = (type: string) =>
    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;

  const TAB_IDS: ActiveTab[] = ["chart", "assignments", "position", "recommendation", "settings"];
  const tabDefinitions = [
    { id: "chart", content: "Size Chart" },
    { id: "assignments", content: `Assignments${assignments.length > 0 ? ` (${assignments.length})` : ""}` },
    { id: "position", content: "Position" },
    { id: "recommendation", content: "AI Recommendation" },
    { id: "settings", content: "Settings" },
  ];
  const selectedTabIndex = TAB_IDS.indexOf(activeTab);
  const handleTabSelect = (index: number) => {
    setActiveTab(TAB_IDS[index]);
  };

  const pageTitle = isNew ? "New Size Chart" : name;
  const pageSubtitle = hasUnsavedChanges ? "(unsaved)" : undefined;

  return (
    <Page
      title={pageTitle}
      subtitle={pageSubtitle}
      backAction={{ onAction: () => navigate("/app/size-charts") }}
      primaryAction={
        <Button
          variant="primary"
          onClick={handleSave}
          loading={isSaving}
          disabled={isSaving}
        >
          {isSaving ? "Saving..." : "Save"}
        </Button>
      }
      secondaryActions={[
        {
          content: status === "active" ? "Unpublish" : "Publish",
          onAction: handleToggleStatus,
          loading: isTogglingStatus,
          disabled: isNew || isTogglingStatus,
        },
        {
          content: "Duplicate",
          onAction: handleDuplicate,
          loading: isDuplicating,
          disabled: isNew || isDuplicating,
        },
      ]}
    >
      <Layout>
        {/* Main content area */}
        <Layout.Section>
          <BlockStack gap="400">
            {/* Unsaved changes banner */}
            {hasUnsavedChanges && (
              <Banner tone="warning" onDismiss={() => {}}>
                <Text as="p" variant="bodyMd">
                  You have unsaved changes. Click Save to keep your edits.
                </Text>
              </Banner>
            )}

            {/* ============================================================ */}
            {/* Tab navigation                                                */}
            {/* ============================================================ */}
            <Tabs
              tabs={tabDefinitions}
              selected={selectedTabIndex}
              onSelect={handleTabSelect}
              fitted
            />

            {/* ============================================================ */}
            {/* TAB: Size Chart                                               */}
            {/* ============================================================ */}
            {activeTab === "chart" && (
              <BlockStack gap="400">
                {/* General Settings card */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack gap="400" align="start" blockAlign="center">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        General Settings
                      </Text>
                      <Badge tone={status === "active" ? "success" : "new"}>
                        {status === "active" ? "Published" : "Draft"}
                      </Badge>
                    </InlineStack>
                    <TextField
                      label="Chart name"
                      value={name}
                      onChange={(value) => setName(value)}
                      placeholder="e.g. Women's Tops Size Chart"
                      autoComplete="off"
                    />
                    <Select
                      label="Category"
                      value={category}
                      onChange={(value) => setCategory(value)}
                      options={CATEGORIES}
                    />
                  </BlockStack>
                </Card>

                {/* Size Table card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Size Table
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Click any cell to edit. Click a column header to rename it. Use the + buttons to add rows or columns.
                      </Text>
                    </BlockStack>
                    <TableEditor data={chartData} onChange={setChartData} />
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Assignments                                              */}
            {/* ============================================================ */}
            {activeTab === "assignments" && (
              <BlockStack gap="400">
                {/* Current Assignments card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Current Assignments
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        This chart will appear on matching product pages.
                      </Text>
                    </BlockStack>

                    {/* New chart info banner */}
                    {isNew && (
                      <Banner tone="info">
                        <Text as="p" variant="bodyMd">
                          Save the chart first to add product assignments.
                        </Text>
                      </Banner>
                    )}

                    {/* Existing assignments list */}
                    {assignments.length > 0 && (
                      <ResourceList
                        resourceName={{ singular: "assignment", plural: "assignments" }}
                        items={assignments}
                        renderItem={(assignment) => (
                          <ResourceItem
                            id={assignment.id}
                            onClick={() => {}}
                            shortcutActions={[
                              {
                                content: "Remove",
                                onAction: () => handleRemoveAssignment(assignment.id),
                              },
                            ]}
                            persistActions
                          >
                            <InlineStack gap="400" blockAlign="center">
                              <Badge tone="info">
                                {assignmentTypeLabel(assignment.assignmentType)}
                              </Badge>
                              <Text as="span" variant="bodyMd" fontWeight="semibold">
                                {assignment.assignmentValue === "*"
                                  ? "All products"
                                  : assignment.assignmentValue}
                              </Text>
                            </InlineStack>
                          </ResourceItem>
                        )}
                      />
                    )}

                    {/* Empty state */}
                    {assignments.length === 0 && !isNew && (
                      <EmptyState
                        heading="No assignments yet"
                        image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                      >
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Add an assignment below to show this chart on product pages.
                        </Text>
                      </EmptyState>
                    )}
                  </BlockStack>
                </Card>

                {/* Add Assignment card */}
                {!isNew && (
                  <Card>
                    <BlockStack gap="400">
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">
                          Add Assignment
                        </Text>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Target by product, collection, tag, or product type.
                        </Text>
                      </BlockStack>
                      <InlineStack gap="400" blockAlign="end" wrap={false}>
                        <div style={{ flex: "0 0 200px" }}>
                          <Select
                            label="Type"
                            value={newAssignmentType}
                            onChange={(value) => setNewAssignmentType(value)}
                            options={ASSIGNMENT_TYPES}
                          />
                        </div>
                        {newAssignmentType !== "all" && (
                          <div
                            role="presentation"
                            style={{ flex: 1 }}
                            onKeyDown={(e: React.KeyboardEvent) => {
                              if (e.key === "Enter") {
                                e.preventDefault();
                                handleAddAssignment();
                              }
                            }}
                          >
                            <TextField
                              label="Value"
                              value={newAssignmentValue}
                              onChange={(value) => setNewAssignmentValue(value)}
                              placeholder={
                                newAssignmentType === "tag"
                                  ? "e.g. summer-sale"
                                  : newAssignmentType === "product_type"
                                    ? "e.g. T-Shirts"
                                    : newAssignmentType === "collection"
                                      ? "e.g. gid://shopify/Collection/123"
                                      : "e.g. gid://shopify/Product/123"
                              }
                              autoComplete="off"
                            />
                          </div>
                        )}
                        <Button
                          variant="primary"
                          onClick={handleAddAssignment}
                          loading={assignmentFetcher.state !== "idle"}
                        >
                          Add
                        </Button>
                      </InlineStack>
                    </BlockStack>
                  </Card>
                )}
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Position                                                 */}
            {/* ============================================================ */}
            {activeTab === "position" && (
              <BlockStack gap="400">
                {/* Priority card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Display Priority
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        When multiple charts match a product, the one with the lowest priority number is shown first.
                      </Text>
                    </BlockStack>
                    <InlineStack gap="400" blockAlign="center">
                      <div style={{ width: "120px" }}>
                        <TextField
                          label="Priority level"
                          type="number"
                          value={String(priority)}
                          onChange={(value) =>
                            setPriority(Math.max(1, Math.min(100, parseInt(value, 10) || 1)))
                          }
                          min={1}
                          max={100}
                          autoComplete="off"
                        />
                      </div>
                      <div style={{ paddingTop: "20px" }}>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {priority === 1
                            ? "Highest priority"
                            : priority <= 5
                              ? "High priority"
                              : priority <= 20
                                ? "Medium priority"
                                : "Low priority"}
                        </Text>
                      </div>
                    </InlineStack>
                  </BlockStack>
                </Card>

                {/* Display Position card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Widget Button Position
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Choose where the &quot;Size Guide&quot; button appears on your product pages.
                      </Text>
                    </BlockStack>
                    <ChoiceList
                      title="Widget button position"
                      titleHidden
                      choices={[
                        {
                          value: "floating",
                          label: "Floating button",
                          helpText: "A floating button appears near the size selector \u2014 highest visibility",
                        },
                        {
                          value: "above_desc",
                          label: "Above description",
                          helpText: "Shown above the product description section",
                        },
                        {
                          value: "below_desc",
                          label: "Below description",
                          helpText: "Shown below the product description section",
                        },
                      ]}
                      selected={[buttonPosition]}
                      onChange={(selected) =>
                        setButtonPosition(selected[0] as "floating" | "above_desc" | "below_desc")
                      }
                    />
                  </BlockStack>
                </Card>

                {/* Country Targeting card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Country Targeting
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Limit this chart to customers in specific countries (e.g. show EU sizing only in Europe).
                      </Text>
                    </BlockStack>
                    <ChoiceList
                      title="Country targeting"
                      titleHidden
                      choices={[
                        {
                          value: "all",
                          label: "All countries",
                          helpText: "Show this chart to all visitors regardless of location",
                        },
                        {
                          value: "selected",
                          label: "Specific countries",
                          helpText: "Restrict to selected country codes (e.g. US, GB, DE)",
                        },
                      ]}
                      selected={[countries]}
                      onChange={(selected) =>
                        setCountries(selected[0] as "all" | "selected")
                      }
                    />
                    {countries === "selected" && (
                      <BlockStack gap="200">
                        <TextField
                          label="Country codes"
                          value={selectedCountries}
                          onChange={(value) => setSelectedCountries(value)}
                          placeholder="e.g. US, GB, DE, FR, CA"
                          autoComplete="off"
                        />
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Comma-separated ISO 3166-1 alpha-2 codes. Leave blank to match all countries.
                        </Text>
                      </BlockStack>
                    )}
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: AI Recommendation                                        */}
            {/* ============================================================ */}
            {activeTab === "recommendation" && (
              <BlockStack gap="400">
                {/* Enable toggle card */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack gap="400" align="space-between" blockAlign="start">
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">
                          AI Size Recommendation
                        </Text>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          When enabled, customers can enter their height, weight, and body type to get a personalized size recommendation for this chart. Recommendations use your size data to predict the best fit.
                        </Text>
                      </BlockStack>
                      <Checkbox
                        label="Enable AI recommendation"
                        labelHidden
                        checked={recommendationEnabled}
                        onChange={(checked) => setRecommendationEnabled(checked)}
                      />
                    </InlineStack>
                    {recommendationEnabled && (
                      <Banner tone="success">
                        <Text as="p" variant="bodyMd">
                          Customers will see a &quot;Find My Size&quot; button on your product page. Make sure your chart has at least 3 size rows with chest and waist data for best accuracy.
                        </Text>
                      </Banner>
                    )}
                  </BlockStack>
                </Card>

                {/* How it works card */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      How AI Recommendations Work
                    </Text>
                    <BlockStack gap="400">
                      {[
                        { step: "1", title: "Customer enters measurements", desc: "Height, weight, and body type are collected via a short form shown next to your size chart." },
                        { step: "2", title: "AI matches to your size data", desc: "Our algorithm cross-references the inputs with your chart rows to find the closest fit, weighted by body type." },
                        { step: "3", title: "Personalized recommendation shown", desc: "The recommended size is highlighted in the chart with a confidence indicator (high/medium/low)." },
                      ].map((item) => (
                        <InlineStack key={item.step} gap="400" blockAlign="start">
                          <Box
                            minWidth="28px"
                            minHeight="28px"
                            borderRadius="full"
                            background="bg-fill-info"
                          >
                            <InlineStack align="center" blockAlign="center">
                              <Text as="span" variant="bodySm" fontWeight="bold" tone="text-inverse">
                                {item.step}
                              </Text>
                            </InlineStack>
                          </Box>
                          <BlockStack gap="100">
                            <Text as="p" variant="bodyMd">
                              {item.title}
                            </Text>
                            <Text as="p" variant="bodyMd" tone="subdued">
                              {item.desc}
                            </Text>
                          </BlockStack>
                        </InlineStack>
                      ))}
                    </BlockStack>
                  </BlockStack>
                </Card>

                {/* Requirements card */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      Requirements for Best Accuracy
                    </Text>
                    <List>
                      <List.Item>At least 3 size rows (S, M, L or numeric sizes)</List.Item>
                      <List.Item>Chest and/or waist measurements in your chart columns</List.Item>
                      <List.Item>AI Recommender enabled in Recommender settings</List.Item>
                      <List.Item>Starter plan or above</List.Item>
                    </List>
                    <Button url="/app/recommender">Configure Recommender Settings</Button>
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Settings                                                 */}
            {/* ============================================================ */}
            {activeTab === "settings" && (
              <BlockStack gap="400">
                {/* Chart Information */}
                {!isNew && chart && (
                  <Card>
                    <BlockStack gap="400">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Chart Information
                      </Text>
                      <BlockStack gap="200">
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Status</Text>
                          <Badge tone={status === "active" ? "success" : undefined}>
                            {status === "active" ? "Published" : "Draft"}
                          </Badge>
                        </InlineStack>
                        <Divider />
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Category</Text>
                          <Badge tone="info">{category}</Badge>
                        </InlineStack>
                        <Divider />
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Sizes</Text>
                          <Text as="p" variant="bodyMd">{chartData.rows.length} rows, {chartData.headers.length} columns</Text>
                        </InlineStack>
                        <Divider />
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Assignments</Text>
                          <Text as="p" variant="bodyMd">{assignments.length} product rule{assignments.length !== 1 ? "s" : ""}</Text>
                        </InlineStack>
                        <Divider />
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Created</Text>
                          <Text as="p" variant="bodyMd">{formatDate(chart.createdAt)}</Text>
                        </InlineStack>
                        <Divider />
                        <InlineStack gap="400" blockAlign="center">
                          <Text as="p" variant="bodyMd" tone="subdued">Last updated</Text>
                          <Text as="p" variant="bodyMd">{formatDate(chart.updatedAt)}</Text>
                        </InlineStack>
                      </BlockStack>
                    </BlockStack>
                  </Card>
                )}

                {/* How to Measure card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        How to Measure
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        This guide is shown alongside your size chart to help customers measure correctly.
                      </Text>
                    </BlockStack>
                    <Box padding="400" background="bg-surface-secondary" borderRadius="200">
                      <BlockStack gap="400">
                        <Text as="p" variant="bodyMd" fontWeight="semibold">
                          Measurement Instructions
                        </Text>
                        <List>
                          <List.Item>
                            <strong>Chest:</strong> Measure around the fullest part of your chest, keeping the tape parallel to the floor.
                          </List.Item>
                          <List.Item>
                            <strong>Waist:</strong> Measure around the narrowest part of your waist, typically 1 inch above the navel.
                          </List.Item>
                          <List.Item>
                            <strong>Hips:</strong> Measure around the fullest part of your hips, approximately 8 inches below the waist.
                          </List.Item>
                          <List.Item>
                            <strong>Inseam:</strong> Measure from the crotch seam down to the ankle bone along the inside of the leg.
                          </List.Item>
                        </List>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Tip: Use a soft measuring tape and measure directly on the skin or over light clothing for the most accurate fit.
                        </Text>
                      </BlockStack>
                    </Box>
                  </BlockStack>
                </Card>

                {/* Danger Zone */}
                {!isNew && (
                  <Card>
                    <BlockStack gap="400">
                      <Text as="h2" variant="headingMd" fontWeight="bold" tone="critical">
                        Danger Zone
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Permanently deletes this chart and all its product assignments. This action cannot be undone.
                      </Text>
                      <assignmentFetcher.Form method="post">
                        <input type="hidden" name="intent" value="delete" />
                        <Button submit tone="critical">
                          Delete this chart
                        </Button>
                      </assignmentFetcher.Form>
                    </BlockStack>
                  </Card>
                )}
              </BlockStack>
            )}
          </BlockStack>
        </Layout.Section>

        {/* ================================================================ */}
        {/* SIDEBAR — Live chart preview                                      */}
        {/* ================================================================ */}
        <Layout.Section variant="oneThird">
          <ChartPreview
            data={chartData}
            status={status}
            category={category}
            assignmentCount={assignments.length}
          />
        </Layout.Section>
      </Layout>
    </Page>
  );
}

